const lockLiveRawLeasesOf = `-- name: LockLiveRawLeasesOf :many
SELECT l.id FROM faucet_raw_leases l
WHERE l.principal = $1 AND l.expires_at > $2
ORDER BY l.id
FOR UPDATE
`

type LockLiveRawLeasesOfParams struct {
	Principal string
	Now       time.Time
}

// An open locks every live lease of its principal before it picks one to end,
// so that it waits here for a poll that holds one, and the statements after it
// read the times of the last polls.
func (q *Queries) LockLiveRawLeasesOf(ctx context.Context, arg LockLiveRawLeasesOfParams) ([][]byte, error) {
	rows, err := q.db.QueryContext(ctx, lockLiveRawLeasesOf, arg.Principal, arg.Now)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items [][]byte
	for rows.Next() {
		var id []byte
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockRawLeases = `-- name: LockRawLeases :exec
SELECT pg_advisory_xact_lock(hashtextextended($1::text, 1))
`

func (q *Queries) LockRawLeases(ctx context.Context, principal string) error {
	_, err := q.db.ExecContext(ctx, lockRawLeases, principal)
	return err
}

const lockRawTarget = `-- name: LockRawTarget :exec
SELECT pg_advisory_xact_lock(hashtextextended($1::text || '/' || CASE $2::text
  WHEN 'repo' THEN $3::bigint::text
  WHEN 'owner' THEN 'owner/' || $4::bigint::text
  ELSE $2::text
END, 2))
`

