const readRawLeasePage = `-- name: ReadRawLeasePage :many
WITH head AS (
  SELECT COALESCE(MAX(id), 0)::bigint AS max_id FROM faucet_raw_events
), unread AS (
  SELECT
    u.raw_event_id,
    COALESCE(NOT u.lost AND e.body IS NOT NULL AND ($1::timestamptz IS NULL OR e.received_at >= $1::timestamptz), false) AS served,
    COALESCE(octet_length(e.body), 0)::bigint AS size
  FROM faucet_raw_unread u
  LEFT JOIN faucet_raw_events e ON e.id = u.raw_event_id
  WHERE u.lease_id = $2 AND u.raw_event_id > $3
), ranked AS (
  SELECT
    raw_event_id, served,
    (COUNT(*) FILTER (WHERE served) OVER earlier < $4::bigint
      AND COALESCE(SUM(size) FILTER (WHERE served) OVER earlier, 0) < $5::bigint) AS open
  FROM unread
  WINDOW earlier AS (ORDER BY raw_event_id ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING)
), summary AS (
  SELECT
    (SELECT max_id FROM head)::bigint AS head,
    (COUNT(*) FILTER (WHERE open AND NOT served))::bigint AS skipped,
    COALESCE(MAX(raw_event_id) FILTER (WHERE open), 0)::bigint AS last_open,
    COALESCE(bool_or(NOT open), false)::boolean AS more
  FROM ranked
)
SELECT
  summary.head, summary.skipped, summary.last_open, summary.more,
  e.id, e.delivery_id, e.event, e.action, e.repo_id, e.owner_id, e.body, e.fields, e.received_at
FROM summary
LEFT JOIN ranked r ON r.open AND r.served
LEFT JOIN faucet_raw_events e ON e.id = r.raw_event_id
ORDER BY e.id
`

type ReadRawLeasePageParams struct {
	NotBefore sql.NullTime
	LeaseID   []byte
	After     int64
	RowLimit  int64
	MaxBytes  int64
}

type ReadRawLeasePageRow struct {
	Head       int64
	Skipped    int64
	LastOpen   int64
	More       bool
	ID         sql.NullInt64
	DeliveryID sql.NullString
	Event      sql.NullString
	Action     sql.NullString
	RepoID     sql.NullInt64
	OwnerID    sql.NullInt64
	Body       []byte
	Fields     []string
	ReceivedAt sql.NullTime
}

// A row is open while the page before it holds fewer than row_limit events
// and fewer than max_bytes bytes of bodies: an open row is returned, or passed
// over when it is lost or its event cannot be served, and the first row that
// is not open ends the page.
func (q *Queries) ReadRawLeasePage(ctx context.Context, arg ReadRawLeasePageParams) ([]ReadRawLeasePageRow, error) {
	rows, err := q.db.QueryContext(ctx, readRawLeasePage,
		arg.NotBefore,
		arg.LeaseID,
		arg.After,
		arg.RowLimit,
		arg.MaxBytes,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ReadRawLeasePageRow
	for rows.Next() {
		var i ReadRawLeasePageRow
		if err := rows.Scan(
			&i.Head,
			&i.Skipped,
			&i.LastOpen,
			&i.More,
			&i.ID,
			&i.DeliveryID,
			&i.Event,
			&i.Action,
			&i.RepoID,
			&i.OwnerID,
			&i.Body,
			pq.Array(&i.Fields),
			&i.ReceivedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

