const touchRawLease = `-- name: TouchRawLease :one
WITH found AS (
  SELECT l.id, l.acked_through FROM faucet_raw_leases l
  WHERE l.id = $4 AND l.key_hash = $5
    AND l.target_kind = $6 AND l.repo_id = $7 AND l.owner_id = $8
    AND l.expires_at > $2
  FOR UPDATE
)
UPDATE faucet_raw_leases l
SET acked_through = GREATEST(l.acked_through, $1::bigint), polled_at = $2, expires_at = $3
FROM found
WHERE l.id = found.id
RETURNING found.acked_through AS acked_before
`

type TouchRawLeaseParams struct {
	After      int64
	Now        time.Time
	ExpiresAt  time.Time
	ID         []byte
	KeyHash    []byte
	TargetKind string
	RepoID     int64
	OwnerID    int64
}

func (q *Queries) TouchRawLease(ctx context.Context, arg TouchRawLeaseParams) (int64, error) {
	row := q.db.QueryRowContext(ctx, touchRawLease,
		arg.After,
		arg.Now,
		arg.ExpiresAt,
		arg.ID,
		arg.KeyHash,
		arg.TargetKind,
		arg.RepoID,
		arg.OwnerID,
	)
	var acked_before int64
	err := row.Scan(&acked_before)
	return acked_before, err
}
